BEGIN; CREATE TEMP TABLE measured ("operation_id" character varying(128) NOT NULL,"deployment_id" character varying(128) NOT NULL,"tenant_id" uuid NOT NULL,"user_id" uuid NOT NULL,"created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL);CREATE UNIQUE INDEX measured_index_0 ON measured USING btree (operation_id);CREATE UNIQUE INDEX measured_index_1 ON measured USING btree (user_id);INSERT INTO measured(operation_id,deployment_id,tenant_id,user_id) SELECT md5('operation-'||i)::uuid::text,'fixture-deployment','00000000-0000-0000-0000-000000000001',md5('user-'||i)::uuid FROM generate_series(1,10000) n(i); SELECT json_build_object('rows',count(*),'avg_tuple_bytes',avg(pg_column_size(d)),'heap_bytes',pg_table_size('measured'),'index_bytes',pg_indexes_size('measured'),'total_bytes',pg_total_relation_size('measured'),'dropped_slots',(SELECT count(*) FROM pg_attribute WHERE attrelid='measured'::regclass AND attnum>0 AND attisdropped)) FROM measured d; ROLLBACK;